\section{引言}
注意力机制\cite{vaswani2017attention}与残差网络\cite{he2016deep}是近年来深度学习的重要进展。
本文使用 \TeX{}\cite{knuth1984texbook} 与 \LaTeX{}\cite{lamport1994latex} 排版。

\section{方法}
\subsection{问题定义}
给定训练集 $\mathcal{D}=\{(x_i,y_i)\}_{i=1}^{n}$，目标是最小化带正则项的经验风险：
\begin{equation}
  \min_{\theta}\ \frac{1}{n}\sum_{i=1}^{n}\ell\bigl(f_\theta(x_i),\,y_i\bigr)
  + \lambda\lVert\theta\rVert_2^2 ,
  \label{eq:loss}
\end{equation}
其中 $\lambda>0$ 为正则化系数。对式~\eqref{eq:loss} 求梯度并迭代更新参数：
\begin{align}
  \nabla_\theta J &= \frac{1}{n}\sum_{i=1}^{n}\nabla_\theta \ell_i + 2\lambda\theta , \label{eq:grad}\\
  \theta_{t+1}    &= \theta_t - \eta\,\nabla_\theta J . \label{eq:update}
\end{align}

\begin{theorem}\label{thm:conv}
若 $J$ 是 $L$-光滑的凸函数，且学习率 $\eta\le 1/L$，则梯度下降法产生的目标函数值收敛到最优值。
\end{theorem}

\subsection{算法流程}
算法~\ref{alg:sgd} 给出了完整的训练流程。

\begin{algorithm}[htbp]
  \caption{小批量随机梯度下降}\label{alg:sgd}
  \KwIn{训练集 $\mathcal{D}$，学习率 $\eta$，迭代轮数 $T$}
  \KwOut{模型参数 $\theta$}
  随机初始化 $\theta$\;
  \For{$t \leftarrow 1$ \KwTo $T$}{
    从 $\mathcal{D}$ 中随机采样一个小批量 $\mathcal{B}$\;
    按式~\eqref{eq:update} 更新 $\theta$\;
  }
  \Return{$\theta$}\;
\end{algorithm}

代码~\ref{lst:train} 是对应的 Python 实现。

\begin{lstlisting}[language=Python, caption={训练循环}, label={lst:train}]
for epoch in range(num_epochs):
    for x, y in loader:
        loss = criterion(model(x), y)
        optimizer.zero_grad()
        loss.backward()
        optimizer.step()
\end{lstlisting}

